1	"use client";
2	
3	import * as React from "react";
4	import { DataTable, type Column } from "@/components/ui/DataTable";
5	import { formatCents } from "@/lib/format";
6	import { t } from "@/lib/i18n";
7	
8	export interface SessionRowData {
9	  id: string;
10	  dateLabel: string;
11	  endedAtMs: number;
12	  durationLabel: string;
13	  blockMinutes: number;
14	  overageMinutes: number;
15	  earningsCents: number;
16	  rating: number | null;
17	}
18	
19	export function SessionsTable({ rows }: { rows: SessionRowData[] }) {
20	  const columns: Column<SessionRowData>[] = [
21	    {
22	      key: "dateLabel",
23	      header: t("provider.colDate"),
24	      sortable: true,
25	      sortValue: (r) => r.endedAtMs,
26	    },
27	    { key: "durationLabel", header: t("provider.colDuration") },
28	    {
29	      key: "blockMinutes",
30	      header: t("provider.colBlock"),
31	      render: (r) => t("provider.minutesShort", { minutes: r.blockMinutes }),
32	    },
33	    {
34	      key: "overageMinutes",
35	      header: t("provider.colOverage"),
36	      render: (r) =>
37	        r.overageMinutes > 0
38	          ? t("provider.minutesShort", { minutes: r.overageMinutes })
39	          : t("provider.noRatingShort"),
40	    },
41	    {
42	      key: "earningsCents",
43	      header: t("provider.colEarnings"),
44	      align: "right",
45	      sortable: true,
46	      sortValue: (r) => r.earningsCents,
47	      render: (r) => formatCents(r.earningsCents),
48	    },
49	    {
50	      key: "rating",
51	      header: t("provider.colRating"),
52	      render: (r) => (r.rating ? `★ ${r.rating}` : t("provider.noRatingShort")),
53	    },
54	  ];
55	
56	  return (
57	    <DataTable
58	      caption={t("provider.recentSessionsCaption")}
59	      columns={columns}
60	      rows={rows}
61	      getRowKey={(r) => r.id}
62	      emptyText={t("provider.recentSessionsNone")}
63	    />
64	  );
65	}
