1	"use client";
2	
3	import * as React from "react";
4	import { CalendarCheck, Clock } from "lucide-react";
5	import { DataTable, type Column } from "@/components/ui/DataTable";
6	import { StatusBadge } from "@/components/ui/StatusBadge";
7	import { formatCents } from "@/lib/format";
8	import { t } from "@/lib/i18n";
9	
10	export interface PayoutRowData {
11	  id: string;
12	  periodLabel: string;
13	  periodEndMs: number;
14	  amountCents: number;
15	  status: "scheduled" | "paid";
16	}
17	
18	export function PayoutsTable({ rows }: { rows: PayoutRowData[] }) {
19	  const columns: Column<PayoutRowData>[] = [
20	    {
21	      key: "periodLabel",
22	      header: t("provider.colPeriod"),
23	      sortable: true,
24	      sortValue: (r) => r.periodEndMs,
25	    },
26	    {
27	      key: "amountCents",
28	      header: t("provider.colAmount"),
29	      align: "right",
30	      sortable: true,
31	      sortValue: (r) => r.amountCents,
32	      render: (r) => formatCents(r.amountCents),
33	    },
34	    {
35	      key: "status",
36	      header: t("provider.colStatus"),
37	      render: (r) =>
38	        r.status === "paid" ? (
39	          <StatusBadge tone="success" icon={CalendarCheck}>
40	            {t("provider.payoutPaid")}
41	          </StatusBadge>
42	        ) : (
43	          <StatusBadge tone="warning" icon={Clock}>
44	            {t("provider.payoutScheduled")}
45	          </StatusBadge>
46	        ),
47	    },
48	  ];
49	
50	  return (
51	    <DataTable
52	      caption={t("provider.payoutHistoryCaption")}
53	      columns={columns}
54	      rows={rows}
55	      getRowKey={(r) => r.id}
56	      emptyText={t("provider.payoutsNone")}
57	    />
58	  );
59	}
