27	
28	const TOTAL_STEPS = 4;
29	
30	function dollarsToCents(value: string): number {
31	  const n = Number(value);
32	  return Number.isFinite(n) && n >= 0 ? Math.round(n * 100) : 0;
33	}
34	
35	export function OnboardingFlow({
36	  providerId,
37	  initial,
38	  keepPct,
39	  feePct,
