42	  initial: OnboardingInitial;
43	  keepPct: number;
44	  feePct: number;
45	}) {
46	  const router = useRouter();
47	  const { announce } = useToast();
48	  const [step, setStep] = React.useState(1);
49	  const [submitting, setSubmitting] = React.useState(false);
50	  const [error, setError] = React.useState<string | null>(null);
51	
52	  const [displayName, setDisplayName] = React.useState(initial.displayName);
53	  const [bio, setBio] = React.useState(initial.bio);
54	  const [voiceIntroPath, setVoiceIntroPath] = React.useState(initial.voiceIntroPath);
