70	      ? list.filter((v) => v !== value)
71	      : [...list, value];
72	  }
73	
74	  function goNext() {
75	    if (step < TOTAL_STEPS) {
76	      setStep(step + 1);
77	      announce(t("provider.stepOf", { current: step + 1, total: TOTAL_STEPS }));
78	    }
