117	      dollarsToCents(price45) > 0,
118	  };
119	
120	  return (
121	    <div className="flex flex-col gap-6">
122	      <p className="text-base font-bold text-ink-soft" aria-live="polite">
123	        {t("provider.stepOf", { current: step, total: TOTAL_STEPS })}
124	      </p>
125	
126	      {error ? (
127	        <p
128	          role="alert"
129	          className="flex items-start gap-2 rounded-card border-l-4 border-alert bg-alert-tint px-4 py-3 text-base"
130	        >
