175	          </Field>
176	        </section>
177	      ) : null}
178	
179	      {step === 2 ? (
180	        <section className="flex flex-col gap-5">
181	          <div>
182	            <h2 ref={headingRef} tabIndex={-1} className="text-h2 outline-none">
183	              {t("provider.step2Title")}
