185	            <p className="mt-1 text-lg text-ink-soft">{t("provider.step2Help")}</p>
186	          </div>
187	          <fieldset className="flex flex-col gap-3">
188	            <legend className="text-base font-bold text-ink">
189	              {t("provider.topicsLabel")}
