206	            </legend>
207	            <div className="flex flex-wrap gap-2.5">
208	              {LANGUAGES.map((lang) => (
209	                <Chip
210	                  key={lang}
211	                  selected={languages.includes(lang)}
212	                  onClick={() => setLanguages(toggle(languages, lang))}
213	                >
214	                  {lang}
215	                </Chip>
216	              ))}
217	            </div>
218	          </fieldset>
219	        </section>
220	      ) : null}
221	
222	      {step === 3 ? (
223	        <section className="flex flex-col gap-5">
224	          <div>
225	            <h2 ref={headingRef} tabIndex={-1} className="text-h2 outline-none">
