230	            </p>
231	          </div>
232	          <div className="grid grid-cols-2 gap-4 max-sm:grid-cols-1">
233	            {(
234	              [
235	                ["provider.price15Label", price15, setPrice15],
236	                ["provider.price30Label", price30, setPrice30],
237	                ["provider.price45Label", price45, setPrice45],
238	                ["provider.overageLabel", overage, setOverage],
239	              ] as const
240	            ).map(([labelKey, value, setter]) => (
241	              <Field
242	                key={labelKey}
243	                label={t(labelKey)}
244	                hint={t("provider.dollarsHint")}
245	              >
246	                {(p) => (
247	                  <Input
248	                    {...p}
249	                    type="number"
250	                    inputMode="decimal"
251	                    min={0}
252	                    step="0.01"
253	                    value={value}
254	                    onChange={(e) => setter(e.target.value)}
255	                  />
256	                )}
257	              </Field>
258	            ))}
259	          </div>
260	          <label className="flex items-center gap-3 rounded-card border border-border bg-surface p-4 text-base font-bold text-ink">
261	            <input
