271	
272	      {step === 4 ? (
273	        <section className="flex flex-col gap-5">
274	          <div>
275	            <h2 ref={headingRef} tabIndex={-1} className="text-h2 outline-none">
276	              {t("provider.step4Title")}
277	            </h2>
278	            <p className="mt-1 text-lg text-ink-soft">{t("provider.step4Help")}</p>
279	          </div>
280	          <ul className="flex flex-col gap-2">
281	            {(
282	              [
283	                ["provider.verifyVoice", done.voice],
284	                ["provider.verifyTopics", done.topics],
285	                ["provider.verifyPricing", done.pricing],
286	              ] as const
287	            ).map(([labelKey, ok]) => (
288	              <li
289	                key={labelKey}
290	                className="flex items-center justify-between rounded-card border border-border bg-surface px-4 py-3 text-base"
