1	"use client";
2	
3	import * as React from "react";
4	import { Mic, Square, Play, Pause, Upload, CircleCheck } from "lucide-react";
5	import { Button } from "@/components/ui/Button";
6	import { createClient } from "@/lib/supabase/client";
7	import { VOICE_BUCKET } from "@/lib/constants";
8	import { t } from "@/lib/i18n";
9	import { useToast } from "@/components/ui/Toast";
10	
11	interface Props {
12	  providerId: string;
13	  /** Existing stored path, if any. */
14	  initialPath?: string | null;
15	  onUploaded: (path: string | null) => void;
16	}
17	
18	/**
19	 * Record (MediaRecorder) or upload a voice intro and store it in the private
20	 * voice-intros bucket. Fully labelled, keyboard-operable; degrades to file
21	 * upload where recording isn't available. Audio is optional — the written
22	 * intro is the accessible equivalent.
23	 */
24	export function VoiceIntroRecorder({ providerId, initialPath, onUploaded }: Props) {
25	  const { announce } = useToast();
26	  const [recording, setRecording] = React.useState(false);
27	  const [audioUrl, setAudioUrl] = React.useState<string | null>(null);
28	  const [playing, setPlaying] = React.useState(false);
29	  const [uploading, setUploading] = React.useState(false);
30	  const [hasIntro, setHasIntro] = React.useState(!!initialPath);
31	  const [error, setError] = React.useState<string | null>(null);
32	
33	  const recorderRef = React.useRef<MediaRecorder | null>(null);
34	  const chunksRef = React.useRef<Blob[]>([]);
35	  const audioRef = React.useRef<HTMLAudioElement | null>(null);
36	
37	  const canRecord =
38	    typeof window !== "undefined" &&
39	    typeof window.MediaRecorder !== "undefined" &&
40	    !!navigator.mediaDevices?.getUserMedia;
41	
42	  async function upload(blob: Blob) {
43	    setUploading(true);
44	    setError(null);
45	    try {
46	      const supabase = createClient();
47	      const path = `${providerId}/intro.webm`;
48	      const { error: upErr } = await supabase.storage
49	        .from(VOICE_BUCKET)
50	        .upload(path, blob, {
51	          upsert: true,
52	          contentType: blob.type || "audio/webm",
53	        });
54	      if (upErr) throw upErr;
55	      setHasIntro(true);
56	      onUploaded(path);
57	      announce(t("provider.recordingReady"));
58	    } catch {
59	      setError(t("provider.recordingUnsupported"));
60	    } finally {
61	      setUploading(false);
62	    }
63	  }
64	
65	  async function startRecording() {
66	    setError(null);
67	    try {
68	      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
69	      const recorder = new MediaRecorder(stream);
70	      chunksRef.current = [];
71	      recorder.ondataavailable = (e) => chunksRef.current.push(e.data);
72	      recorder.onstop = () => {
73	        const blob = new Blob(chunksRef.current, { type: "audio/webm" });
74	        if (audioUrl) URL.revokeObjectURL(audioUrl);
75	        setAudioUrl(URL.createObjectURL(blob));
76	        stream.getTracks().forEach((track) => track.stop());
77	        void upload(blob);
78	      };
79	      recorderRef.current = recorder;
80	      recorder.start();
81	      setRecording(true);
82	      announce(t("provider.recordLabel"));
83	    } catch {
84	      setError(t("provider.recordingUnsupported"));
85	    }
86	  }
87	
88	  function stopRecording() {
89	    recorderRef.current?.stop();
90	    setRecording(false);
91	  }
92	
93	  function togglePlay() {
94	    const el = audioRef.current;
95	    if (!el) return;
96	    if (playing) {
97	      el.pause();
98	      setPlaying(false);
99	    } else {
100	      void el.play();
101	      setPlaying(true);
102	    }
103	  }
104	
105	  async function onFile(e: React.ChangeEvent<HTMLInputElement>) {
106	    const file = e.target.files?.[0];
107	    if (!file) return;
108	    if (audioUrl) URL.revokeObjectURL(audioUrl);
109	    setAudioUrl(URL.createObjectURL(file));
110	    await upload(file);
111	  }
112	
113	  return (
114	    <div className="flex flex-col gap-4 rounded-card border border-border bg-surface p-5">
115	      <div className="flex flex-wrap items-center gap-3">
116	        {canRecord && !recording ? (
117	          <Button icon={Mic} onClick={startRecording} disabled={uploading}>
118	            {hasIntro ? t("provider.rerecordLabel") : t("provider.recordLabel")}
119	          </Button>
120	        ) : null}
121	        {recording ? (
122	          <Button variant="danger" icon={Square} onClick={stopRecording}>
123	            {t("provider.stopLabel")}
124	          </Button>
125	        ) : null}
126	
127	        {audioUrl ? (
128	          <Button
129	            variant="ghost"
130	            icon={playing ? Pause : Play}
131	            onClick={togglePlay}
132	          >
133	            {playing ? t("provider.pauseLabel") : t("provider.playLabel")}
134	          </Button>
135	        ) : null}
136	
137	        <label className="inline-flex min-h-12 cursor-pointer items-center gap-2 rounded-btn border border-border-strong bg-surface px-4 text-base font-bold text-primary hover:bg-primary-tint">
138	          <Upload size={20} strokeWidth={2} aria-hidden="true" />
139	          {t("provider.uploadLabel")}
140	          <input
141	            type="file"
142	            accept="audio/*"
143	            className="sr-only"
144	            onChange={onFile}
145	            disabled={uploading}
146	          />
147	        </label>
148	      </div>
149	
150	      <p className="flex items-center gap-2 text-base text-ink-soft" aria-live="polite">
151	        {hasIntro ? (
152	          <>
153	            <CircleCheck
154	              size={18}
155	              strokeWidth={2}
156	              aria-hidden="true"
157	              className="text-success"
158	            />
159	            {t("provider.recordingReady")}
160	          </>
161	        ) : uploading ? (
162	          t("ui.loading")
163	        ) : (
164	          t("provider.recordingNone")
165	        )}
166	      </p>
167	
168	      {error ? (
169	        <p role="alert" className="text-base font-semibold text-alert">
170	          {error}
171	        </p>
172	      ) : null}
173	
174	      {audioUrl ? (
175	        <audio
176	          ref={audioRef}
177	          src={audioUrl}
178	          onEnded={() => setPlaying(false)}
179	          className="sr-only"
180	        />
181	      ) : null}
182	    </div>
183	  );
184	}
