10	import { startSession, endSession } from "@/app/(customer)/session/actions";
11	import { t } from "@/lib/i18n";
12	
13	const GUEST = "Guest";
14	const GUEST_COLOR = "#7A6A58";
15	
16	export function ProviderSessionFlow({
17	  bookingId,
18	  blockMinutes,
19	  alreadyInProgress,
20	}: {
21	  bookingId: string;
22	  blockMinutes: number;
23	  alreadyInProgress: boolean;
24	}) {
25	  const router = useRouter();
26	  const [phase, setPhase] = React.useState<"incoming" | "incall">(
27	    alreadyInProgress ? "incall" : "incoming",
28	  );
29	  const [busy, setBusy] = React.useState(false);
30	  const [error, setError] = React.useState<string | null>(null);
31	
32	  async function accept() {
33	    setBusy(true);
34	    setError(null);
35	    const res = await startSession(bookingId);
36	    if (res.error) {
37	      setError(res.error);
38	      setBusy(false);
39	      return;
40	    }
41	    setPhase("incall");
42	  }
43	
44	  if (phase === "incall") {
45	    return (
46	      <CallStage
47	        name={GUEST}
48	        avatarColor={GUEST_COLOR}
49	        endLabel={t("session.endForSafety")}
50	        onEnd={async (elapsed) => {
51	          await endSession(bookingId, elapsed);
52	          router.push(`/provider/session/${bookingId}/summary`);
53	        }}
54	      />
55	    );
56	  }
57	
58	  return (
59	    <Card className="mx-auto flex w-full max-w-xl flex-col items-center gap-6 p-8 text-center max-md:p-6">
60	      <Avatar name={GUEST} color={GUEST_COLOR} size={88} />
61	      <div className="flex flex-col gap-2">
62	        <h1 className="text-h2">{t("session.incomingTitle", { name: GUEST })}</h1>
63	        <p className="text-lg text-ink-soft">
64	          {t("session.incomingBlock", { minutes: blockMinutes })}
65	        </p>
66	      </div>
67	
68	      {error ? (
69	        <p role="alert" className="text-base font-semibold text-alert">
70	          {error}
71	        </p>
72	      ) : null}
73	
74	      <div className="flex w-full flex-col gap-3">
75	        <Button full icon={Phone} onClick={accept} disabled={busy}>
76	          {busy ? t("ui.loading") : t("session.accept")}
77	        </Button>
78	        <Button
79	          full
80	          variant="ghost"
81	          icon={PhoneOff}
82	          onClick={() => router.push("/provider/dashboard")}
83	        >
84	          {t("session.decline")}
85	        </Button>
86	      </div>
87	    </Card>
88	  );
89	}
