1	"use client";
2	
3	import * as React from "react";
4	import { ChevronUp, ChevronDown, ChevronsUpDown } from "lucide-react";
5	import { t } from "@/lib/i18n";
6	
7	export interface Column<T> {
8	  key: string;
9	  header: string;
10	  align?: "left" | "right";
11	  sortable?: boolean;
12	  /** Custom cell content; defaults to String(row[key]). */
13	  render?: (row: T) => React.ReactNode;
14	  /** Value used for sorting; defaults to render-less row[key]. */
15	  sortValue?: (row: T) => string | number;
16	}
17	
18	interface SortState {
19	  key: string;
20	  dir: "asc" | "desc";
21	}
22	
23	/**
24	 * Accessible data table: real `<table>` with a `<caption>`, `<thead>`, and
25	 * `<th scope="col">`. Sortable columns are keyboard-operable `<button>`s; the
26	 * `<th>`'s `aria-sort` reflects state and a live region announces each change.
27	 */
28	export function DataTable<T>({
29	  caption,
30	  columns,
31	  rows,
32	  getRowKey,
33	  captionVisible = false,
34	  emptyText,
35	}: {
36	  caption: string;
37	  columns: Column<T>[];
38	  rows: T[];
39	  getRowKey: (row: T, index: number) => string;
40	  captionVisible?: boolean;
41	  emptyText?: string;
42	}) {
43	  const [sort, setSort] = React.useState<SortState | null>(null);
44	  const [announce, setAnnounce] = React.useState("");
45	
46	  const sorted = React.useMemo(() => {
47	    if (!sort) return rows;
48	    const col = columns.find((c) => c.key === sort.key);
49	    if (!col) return rows;
50	    const value = (row: T): string | number =>
51	      col.sortValue
52	        ? col.sortValue(row)
53	        : ((row as Record<string, unknown>)[col.key] as string | number);
54	    const factor = sort.dir === "asc" ? 1 : -1;
55	    return [...rows].sort((a, b) => {
56	      const av = value(a);
57	      const bv = value(b);
58	      if (av < bv) return -1 * factor;
59	      if (av > bv) return 1 * factor;
60	      return 0;
61	    });
62	  }, [rows, sort, columns]);
63	
64	  function toggleSort(col: Column<T>) {
65	    setSort((prev) => {
66	      const dir: "asc" | "desc" =
67	        prev?.key === col.key && prev.dir === "asc" ? "desc" : "asc";
68	      setAnnounce(
69	        t("table.sortedBy", {
70	          column: col.header,
71	          direction: t(dir === "asc" ? "table.ascending" : "table.descending"),
72	        }),
73	      );
74	      return { key: col.key, dir };
75	    });
76	  }
77	
78	  return (
79	    <div className="overflow-x-auto">
80	      <table className="w-full border-collapse text-left text-base">
81	        <caption
82	          className={captionVisible ? "pb-3 text-left font-display text-h3" : "sr-only"}
83	        >
84	          {caption}
85	        </caption>
86	        <thead>
87	          <tr className="border-b-2 border-border-strong">
88	            {columns.map((col) => {
89	              const active = sort?.key === col.key;
90	              const ariaSort = active
91	                ? sort.dir === "asc"
92	                  ? "ascending"
93	                  : "descending"
94	                : "none";
95	              return (
96	                <th
97	                  key={col.key}
98	                  scope="col"
99	                  aria-sort={col.sortable ? ariaSort : undefined}
100	                  className={[
101	                    "px-3 pb-2.5 pt-1 text-sm font-extrabold uppercase tracking-[0.1em] text-ink-soft",
102	                    col.align === "right" ? "text-right" : "text-left",
103	                  ].join(" ")}
104	                >
105	                  {col.sortable ? (
106	                    <button
107	                      type="button"
108	                      onClick={() => toggleSort(col)}
109	                      className={[
110	                        "inline-flex items-center gap-1 rounded-sm font-extrabold uppercase tracking-[0.1em] text-ink-soft hover:text-ink",
111	                        col.align === "right" ? "flex-row-reverse" : "",
112	                      ].join(" ")}
113	                    >
114	                      {col.header}
115	                      {active ? (
116	                        sort.dir === "asc" ? (
117	                          <ChevronUp size={15} strokeWidth={2.5} aria-hidden="true" />
118	                        ) : (
119	                          <ChevronDown size={15} strokeWidth={2.5} aria-hidden="true" />
120	                        )
121	                      ) : (
122	                        <ChevronsUpDown
123	                          size={15}
124	                          strokeWidth={2}
125	                          aria-hidden="true"
126	                          className="text-ink-faint"
127	                        />
128	                      )}
129	                    </button>
130	                  ) : (
131	                    col.header
132	                  )}
133	                </th>
134	              );
135	            })}
136	          </tr>
137	        </thead>
138	        <tbody>
139	          {sorted.length === 0 ? (
140	            <tr>
141	              <td
142	                colSpan={columns.length}
143	                className="px-3 py-8 text-center text-base text-ink-soft"
144	              >
145	                {emptyText ?? t("table.empty")}
146	              </td>
147	            </tr>
148	          ) : (
149	            sorted.map((row, i) => (
150	              <tr
151	                key={getRowKey(row, i)}
152	                className="border-b border-border transition-colors duration-200 last:border-0 hover:bg-surface-sunk/50"
153	              >
154	                {columns.map((col) => (
155	                  <td
156	                    key={col.key}
157	                    className={[
158	                      "px-3 py-4 text-ink tabular-nums",
159	                      col.align === "right" ? "text-right" : "text-left",
160	                    ].join(" ")}
161	                  >
162	                    {col.render
163	                      ? col.render(row)
164	                      : String((row as Record<string, unknown>)[col.key] ?? "")}
165	                  </td>
166	                ))}
167	              </tr>
168	            ))
169	          )}
170	        </tbody>
171	      </table>
172	      <div className="sr-only" aria-live="polite">
173	        {announce}
174	      </div>
175	    </div>
176	  );
177	}
