83	      <div className="flex min-w-0 flex-1 items-center gap-3.5">
84	        <button
85	          type="button"
86	          onClick={toggle}
87	          aria-label={
88	            playing
89	              ? t("ui.pauseVoiceIntro", { name })
90	              : t("ui.playVoiceIntro", { name })
91	          }
92	          aria-pressed={playing}
93	          className={[
94	            "grid flex-none place-items-center rounded-pill bg-primary text-surface shadow-sm",
95	            "transition-[background-color,transform] duration-200 ease-[cubic-bezier(0.33,0.1,0.25,1)]",
96	            "hover:bg-primary-dark active:scale-[0.96] aria-pressed:bg-primary-dark",
97	          ].join(" ")}
98	          style={{ width: diameter, height: diameter }}
99	        >
100	          {playing ? (
101	            <Pause size={big ? 30 : 22} strokeWidth={2} aria-hidden="true" />
102	          ) : (
103	            <Play size={big ? 30 : 22} strokeWidth={2} aria-hidden="true" className="translate-x-[1px]" />
104	          )}
105	        </button>
106	        <div className="flex min-w-0 flex-1 flex-col gap-1">
107	          <span className="truncate text-base font-bold text-ink">
108	            {t("ui.voiceIntroOf", { name })}
109	          </span>
110	          <span className="flex items-center gap-2.5 text-sm text-ink-soft">
111	            <Waveform playing={playing} big={big} />
112	            <span className="whitespace-nowrap">
113	              {playing ? t("ui.playingNow") : t("ui.tapToListen")}
114	            </span>
115	          </span>
116	        </div>
117	      </div>
118	      {big ? (
119	        <p className="border-t border-border pt-4 text-base leading-body text-ink">
120	          <span className="mb-1 block text-xs font-extrabold uppercase tracking-[0.12em] text-ink-soft">
121	            {t("ui.transcript")}
122	          </span>
123	          {intro}
124	        </p>
125	      ) : null}
126	      {audioUrl ? (
127	        <audio
128	          ref={audioRef}
129	          src={audioUrl}
130	          onEnded={() => setPlaying(false)}
131	          className="sr-only"
132	        />
133	      ) : null}
134	    </div>
135	  );
136	}
