"use client";

import * as React from "react";
import { useTransition } from "react";
import { setAvailability } from "@/app/(provider)/provider/actions";
import { Container } from "@/components/shared/Container";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

/**
 * The availability strip — a full-width tonal band (DESIGN_SPEC_V2 §6): teal
 * with cream text while the listener is available, a sunk cream well while
 * offline. State is conveyed by the serif status line and the switch's
 * aria-checked + visible action text — never colour alone. The switch is a
 * real role="switch", ≥48px, keyboard-operable, announced on change.
 */
export function AvailabilityToggle({
  initial,
  disabled,
  statusBadge,
  nextSessionLine,
}: {
  initial: boolean;
  disabled?: boolean;
  /** Server-rendered status pill (approved / pending …) shown in the band. */
  statusBadge?: React.ReactNode;
  /** "Next session: …" line rendered under the status text. */
  nextSessionLine?: string;
}) {
  const [on, setOn] = React.useState(initial);
  const [pending, startTransition] = useTransition();
  const { announce } = useToast();

  function flip() {
    const next = !on;
    setOn(next);
    announce(next ? t("provider.available") : t("provider.offline"), true);
    startTransition(async () => {
      const res = await setAvailability(next);
      if (!res.ok) setOn(!next); // revert on failure
    });
  }

  if (disabled) {
    return (
      <section
        aria-label={t("provider.availabilityHeading")}
        className="w-full bg-surface-sunk py-10 max-md:py-8"
      >
        <Container className="flex flex-wrap items-center justify-between gap-x-8 gap-y-4">
          <div className="flex max-w-[52ch] flex-col gap-2">
            <p className="kicker">{t("provider.availabilityHeading")}</p>
            <p className="font-display text-h3 text-ink">
              {t("provider.availableNotApproved")}
            </p>
          </div>
          {statusBadge}
        </Container>
      </section>
    );
  }

  return (
    <section
      aria-label={t("provider.availabilityHeading")}
      className={[
        "w-full py-10 transition-colors duration-300 max-md:py-8",
        on ? "bg-primary" : "bg-surface-sunk",
      ].join(" ")}
    >
      <Container className="flex flex-wrap items-center justify-between gap-x-10 gap-y-5">
        <div className="flex max-w-[52ch] flex-col gap-2">
          <div className="flex flex-wrap items-center gap-3">
            <p className={["kicker", on ? "text-surface" : ""].filter(Boolean).join(" ")}>
              {t("provider.availabilityHeading")}
            </p>
            {statusBadge}
          </div>
          <p
            className={[
              "font-display text-h2 font-bold tracking-[-0.015em]",
              on ? "text-bg" : "text-ink",
            ].join(" ")}
          >
            {on ? t("provider.available") : t("provider.offline")}
          </p>
          {nextSessionLine ? (
            <p className={["text-base", on ? "text-bg" : "text-ink-soft"].join(" ")}>
              {nextSessionLine}
            </p>
          ) : null}
        </div>

        <button
          type="button"
          role="switch"
          aria-checked={on}
          onClick={flip}
          disabled={pending}
          className={[
            "inline-flex min-h-12 flex-none items-center gap-3 rounded-pill border px-6 py-2.5 text-base font-extrabold",
            "transition-[background-color,border-color,color,transform] duration-200 active:scale-[0.98]",
            "disabled:cursor-not-allowed disabled:opacity-60",
            on
              ? "border-surface/40 bg-transparent text-surface hover:bg-primary-dark"
              : "border-border-strong bg-surface text-primary hover:bg-primary-tint",
          ].join(" ")}
        >
          {/* Decorative track + thumb — the state is carried by aria-checked
              and the visible action text. */}
          <span
            aria-hidden="true"
            className={[
              "relative inline-block h-6 w-11 flex-none rounded-pill transition-colors duration-200",
              on ? "bg-surface/30" : "bg-border-strong",
            ].join(" ")}
          >
            <span
              className={[
                "absolute top-1 size-4 rounded-pill bg-surface transition-[left] duration-200",
                on ? "left-6" : "left-1",
              ].join(" ")}
            />
          </span>
          {on ? t("provider.turnOff") : t("provider.turnOn")}
        </button>
      </Container>
    </section>
  );
}

"use client";

import * as React from "react";
import { useTransition } from "react";
import Link from "next/link";
import { Phone, X, Clock } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Avatar } from "@/components/ui/Avatar";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { declineBooking } from "@/app/(provider)/provider/actions";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

export interface IncomingItem {
  id: string;
  blockMinutes: number;
  status: "confirmed" | "in_progress";
}

const GUEST_COLOR = "#7A6A58";

/**
 * Incoming / upcoming requests — the one place on the dashboard where
 * elevation means something: each request is a white lifted card row with
 * Accept (primary) / Decline (ghost) — DESIGN_SPEC_V2 §4/§6.
 */
export function IncomingRequests({ items }: { items: IncomingItem[] }) {
  const [pending, startTransition] = useTransition();
  const { announce } = useToast();

  function decline(id: string) {
    startTransition(async () => {
      await declineBooking(id);
      announce(t("provider.decline"));
    });
  }

  if (items.length === 0) {
    return (
      <p className="border-t border-border pt-6 font-display text-lg italic text-ink-soft">
        {t("provider.incomingNone")}
      </p>
    );
  }

  return (
    <ul className="flex flex-col gap-4">
      {items.map((item) => (
        <Card
          as="li"
          key={item.id}
          className="flex flex-wrap items-center justify-between gap-x-8 gap-y-4"
        >
          <div className="flex items-center gap-4">
            <Avatar name={t("provider.guest")} color={GUEST_COLOR} size={56} />
            <div className="flex flex-col gap-1">
              <span className="font-display text-h3 text-ink">
                {t("provider.sessionReqLabel", { minutes: item.blockMinutes })}
              </span>
              <StatusBadge
                tone={item.status === "in_progress" ? "info" : "success"}
                icon={item.status === "in_progress" ? Clock : Phone}
              >
                {t("provider.guest")}
              </StatusBadge>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-3">
            <Link href={`/provider/session/${item.id}`} className="rounded-pill">
              <Button icon={Phone}>{t("provider.accept")}</Button>
            </Link>
            <Button
              variant="ghost"
              icon={X}
              onClick={() => decline(item.id)}
              disabled={pending}
            >
              {t("provider.decline")}
            </Button>
          </div>
        </Card>
      ))}
    </ul>
  );
}

