import Link from "next/link";
import { ShieldCheck, ArrowRight, Wallet } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { StatCard } from "@/components/ui/StatCard";
import { StatusBadge, type StatusTone } from "@/components/ui/StatusBadge";
import { Container } from "@/components/shared/Container";
import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
import { AvailabilityToggle } from "@/components/provider/AvailabilityToggle";
import { IncomingRequests } from "@/components/provider/IncomingRequests";
import { SessionsTable } from "@/components/provider/SessionsTable";
import { PayoutsTable } from "@/components/provider/PayoutsTable";
import { requireRole } from "@/lib/auth";
import {
  getOwnProvider,
  listProviderBookings,
  listProviderPayouts,
  listProviderCompletedSessions,
  listProviderReviews,
} from "@/lib/db/queries";
import { summarizeEarnings } from "@/lib/earnings";
import { formatCents, formatRating } from "@/lib/format";
import { nowEpochMs, shortDate, durationLabel } from "@/lib/time";
import { t, type MessageKey } from "@/lib/i18n";
import { type ProviderStatus } from "@/lib/supabase/types";

export const metadata = {
  title: `${t("provider.dashboardTitle")} · ${t("app.name")}`,
};

const STATUS: Record<
  ProviderStatus,
  { titleKey: MessageKey; bodyKey: MessageKey; tone: StatusTone }
> = {
  pending: {
    titleKey: "provider.statusPendingTitle",
    bodyKey: "provider.statusPendingBody",
    tone: "warning",
  },
  approved: {
    titleKey: "provider.statusApprovedTitle",
    bodyKey: "provider.statusApprovedBody",
    tone: "success",
  },
  rejected: {
    titleKey: "provider.statusRejectedTitle",
    bodyKey: "provider.statusRejectedBody",
    tone: "alert",
  },
  suspended: {
    titleKey: "provider.statusSuspendedTitle",
    bodyKey: "provider.statusSuspendedBody",
    tone: "alert",
  },
};

/** Kicker + serif heading pair used above every dashboard group (§3). */
function SectionHeading({
  kicker,
  title,
  action,
}: {
  kicker: string;
  title: string;
  action?: React.ReactNode;
}) {
  return (
    <div className="flex flex-wrap items-end justify-between gap-x-8 gap-y-3">
      <div className="flex flex-col gap-1.5">
        <p className="kicker">{kicker}</p>
        <h2 className="text-h2">{title}</h2>
      </div>
      {action}
    </div>
  );
}

export default async function ProviderDashboardPage() {
  const profile = await requireRole("provider");
  const provider = await getOwnProvider();

  const onboardingComplete =
    !!provider &&
    provider.bio.trim().length > 0 &&
    provider.topics.length > 0 &&
    provider.price_block_30_cents > 0;

  const [bookings, payouts, sessions, reviews] = provider
    ? await Promise.all([
        listProviderBookings(provider.id),
        listProviderPayouts(provider.id),
        listProviderCompletedSessions(provider.id),
        listProviderReviews(provider.id),
      ])
    : [[], [], [], []];

  const earnings = summarizeEarnings({
    sessions,
    tips: reviews.filter((r) => r.tip_cents > 0),
    payouts,
    nowMs: nowEpochMs(),
  });

  const upcoming = bookings.filter(
    (b) => b.status === "confirmed" || b.status === "in_progress",
  );
  const nextScheduled = bookings
    .filter((b) => b.scheduled_at && b.status === "confirmed")
    .sort((a, b) => (a.scheduled_at! < b.scheduled_at! ? -1 : 1))[0];

  const ratingBySession = new Map(
    reviews.filter((r) => r.session_id).map((r) => [r.session_id, r.rating]),
  );

  const status = provider?.status ?? "pending";
  const statusCopy = STATUS[status];

  const sessionRows = sessions.map((s) => ({
    id: s.id,
    dateLabel: shortDate(s.ended_at),
    endedAtMs: s.ended_at ? new Date(s.ended_at).getTime() : 0,
    durationLabel: durationLabel(s.elapsed_seconds),
    blockMinutes: s.block_minutes,
    overageMinutes: s.overage_minutes,
    earningsCents: s.provider_earnings_cents,
    rating: ratingBySession.get(s.id) ?? null,
  }));

  const payoutRows = payouts.map((p) => ({
    id: p.id,
    periodLabel: `${shortDate(p.period_start)} – ${shortDate(p.period_end)}`,
    periodEndMs: new Date(p.period_end).getTime(),
    amountCents: p.amount_cents,
    status: p.status,
  }));

  const healthItems: { labelKey: MessageKey; done: boolean }[] = [
    { labelKey: "provider.phVoiceIntro", done: !!provider?.voice_intro_path },
    { labelKey: "provider.phTopics", done: (provider?.topics.length ?? 0) > 0 },
    {
      labelKey: "provider.phLanguages",
      done: (provider?.languages.length ?? 0) > 0,
    },
    { labelKey: "provider.phPrices", done: (provider?.price_block_30_cents ?? 0) > 0 },
    { labelKey: "provider.phApproval", done: status === "approved" },
    {
      labelKey: "provider.phBgCheck",
      done: provider?.bg_check_status === "clear",
    },
  ];

  const glanceStats = [
    {
      label: t("provider.earningsHeading"),
      value: formatCents(earnings.thisWeekCents),
    },
    { label: t("provider.statPending"), value: formatCents(earnings.pendingCents) },
    {
      label: t("provider.statNextPayout"),
      value: earnings.nextPayoutAt
        ? shortDate(earnings.nextPayoutAt)
        : t("provider.noNextPayout"),
    },
    {
      label: t("provider.statAvgRating"),
      value:
        provider && provider.rating_count > 0
          ? formatRating(provider.rating_avg)
          : t("provider.noRatingShort"),
      hint:
        provider && provider.rating_count > 0
          ? t("provider.reviewsCount", { count: provider.rating_count })
          : undefined,
    },
    {
      label: t("provider.statSessionsWeek"),
      value: earnings.sessionsThisWeek,
    },
  ];

  const nextSessionLine = nextScheduled
    ? `${t("provider.nextScheduled")}: ${shortDate(nextScheduled.scheduled_at)} · ${t("provider.minutesShort", { minutes: nextScheduled.block_minutes })}`
    : t("provider.nextScheduledNone");

  return (
    <div className="flex flex-col">
      <Container className="flex flex-col gap-8 pb-12 max-md:pb-8">
        <DashboardHeader
          kicker={t("provider.dashboardTitle")}
          title={t("provider.welcomeBack", {
            name: provider?.display_name || profile.full_name,
          })}
          description={t("provider.dashboardSubtitle")}
          action={
            <Link href="/provider/onboarding" className="rounded-pill">
              <Button variant="ghost">{t("provider.editProfile")}</Button>
            </Link>
          }
        />

        {!onboardingComplete ? (
          <div className="flex flex-wrap items-center justify-between gap-x-8 gap-y-4 rounded-tile bg-primary-tint p-6">
            <p className="font-display text-h3 text-ink">
              {t("provider.onboardingTitle")}
            </p>
            <Link href="/provider/onboarding" className="rounded-pill">
              <Button icon={ArrowRight}>{t("provider.completeOnboarding")}</Button>
            </Link>
          </div>
        ) : null}
      </Container>

      {/* Availability — full-width tonal band (§6) */}
      <AvailabilityToggle
        initial={provider?.is_available_now ?? false}
        disabled={status !== "approved"}
        nextSessionLine={nextSessionLine}
        statusBadge={
          <StatusBadge tone={statusCopy.tone} icon={ShieldCheck}>
            {t(statusCopy.titleKey)}
          </StatusBadge>
        }
      />

      <Container className="flex flex-col gap-16 pt-16 max-md:gap-12 max-md:pt-10">
        {/* At a glance — flat stat row in a hairline grid, no boxes */}
        <section className="flex flex-col gap-6" aria-label={t("provider.glanceHeading")}>
          <SectionHeading
            kicker={t("provider.kickerGlance")}
            title={t("provider.glanceHeading")}
          />
          <div className="grid border-y border-border sm:grid-cols-2 xl:grid-cols-5 xl:divide-x xl:divide-border">
            {glanceStats.map((s) => (
              <div key={s.label} className="px-2 py-3 xl:px-8 xl:first:pl-0 xl:last:pr-0">
                <StatCard label={s.label} value={s.value} hint={s.hint} />
              </div>
            ))}
          </div>
        </section>

        {/* Incoming & upcoming — elevated white request rows */}
        <section className="flex flex-col gap-6" aria-label={t("provider.incomingHeading")}>
          <SectionHeading
            kicker={t("provider.kickerRequests")}
            title={t("provider.incomingHeading")}
          />
          <IncomingRequests
            items={upcoming.map((b) => ({
              id: b.id,
              blockMinutes: b.block_minutes,
              status: b.status as "confirmed" | "in_progress",
            }))}
          />
        </section>

        {/* Recent sessions — bare table, hairline rows */}
        <section className="flex flex-col gap-6" aria-label={t("provider.recentSessionsHeading")}>
          <SectionHeading
            kicker={t("provider.kickerSessions")}
            title={t("provider.recentSessionsHeading")}
          />
          <SessionsTable rows={sessionRows} />
        </section>

        {/* Contributions & payout history */}
        <section className="flex flex-col gap-6" aria-label={t("provider.earningsHeading")}>
          <SectionHeading
            kicker={t("provider.kickerPayouts")}
            title={t("provider.earningsHeading")}
          />
          <div className="grid border-y border-border sm:grid-cols-3 sm:divide-x sm:divide-border">
            {(
              [
                ["provider.earningsBalanceLabel", earnings.pendingCents],
                ["provider.earningsMonthLabel", earnings.thisMonthCents],
                ["provider.earningsLifetimeLabel", earnings.lifetimeCents],
              ] as const
            ).map(([labelKey, cents]) => (
              <div key={labelKey} className="px-2 py-3 sm:px-8 sm:first:pl-0 sm:last:pr-0">
                <StatCard label={t(labelKey)} value={formatCents(cents)} />
              </div>
            ))}
          </div>
          <h3 className="text-h3">{t("provider.payoutHistoryHeading")}</h3>
          <PayoutsTable rows={payoutRows} />
        </section>

        {/* Recent feedback — serif quote rows */}
        <section className="flex flex-col gap-6" aria-label={t("provider.feedbackHeading")}>
          <SectionHeading
            kicker={t("provider.kickerFeedback")}
            title={t("provider.feedbackHeading")}
          />
          {reviews.length === 0 ? (
            <p className="border-t border-border pt-6 font-display text-lg italic text-ink-soft">
              {t("provider.feedbackNone")}
            </p>
          ) : (
            <ul className="border-t border-border">
              {reviews.slice(0, 5).map((r) => (
                <li
                  key={r.id}
                  className="flex flex-col gap-2.5 border-b border-border py-6"
                >
                  <div className="flex flex-wrap items-center gap-3">
                    <span className="text-base font-bold text-accent-strong">
                      <span aria-hidden="true">
                        {"★".repeat(r.rating)}
                        {"☆".repeat(5 - r.rating)}
                      </span>
                      <span className="sr-only">
                        {t("summary.starLabel", { n: r.rating })}
                      </span>
                    </span>
                    {r.tip_cents > 0 ? (
                      <StatusBadge tone="info" icon={Wallet}>
                        {t("provider.tipLabel", { amount: formatCents(r.tip_cents) })}
                      </StatusBadge>
                    ) : null}
                  </div>
                  {r.comment ? (
                    <blockquote className="max-w-[60ch] font-display text-lg italic leading-snug text-ink">
                      &ldquo;{r.comment}&rdquo;
                    </blockquote>
                  ) : null}
                </li>
              ))}
            </ul>
          )}
        </section>

        {/* Profile health — compact two-column flat checklist */}
        <section className="flex flex-col gap-6" aria-label={t("provider.profileHealthHeading")}>
          <SectionHeading
            kicker={t("provider.kickerHealth")}
            title={t("provider.profileHealthHeading")}
            action={
              <Link href="/provider/onboarding" className="rounded-pill">
                <Button variant="ghost">{t("provider.editProfile")}</Button>
              </Link>
            }
          />
          <ul className="grid gap-x-14 border-t border-border sm:grid-cols-2">
            {healthItems.map((item) => (
              <li
                key={item.labelKey}
                className="flex min-h-12 items-center justify-between gap-3 border-b border-border py-3.5"
              >
                <span className="flex items-center gap-3 text-base font-bold text-ink">
                  <span
                    aria-hidden="true"
                    className={[
                      "size-2.5 flex-none rounded-pill",
                      item.done ? "bg-success" : "bg-border-strong",
                    ].join(" ")}
                  />
                  {t(item.labelKey)}
                </span>
                <span
                  className={[
                    "text-sm font-extrabold uppercase tracking-[0.1em]",
                    item.done
                      ? "text-success-strong"
                      : status === "rejected" || status === "suspended"
                        ? "text-alert"
                        : "text-accent-strong",
                  ].join(" ")}
                >
                  {item.done ? t("provider.phDone") : t("provider.phMissing")}
                </span>
              </li>
            ))}
          </ul>
        </section>
      </Container>
    </div>
  );
}

