"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import { ChevronLeft, ChevronRight, CircleAlert, Phone } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Card } from "@/components/ui/Card";
import { Field, Input } from "@/components/ui/Field";
import { Chip } from "@/components/ui/Chip";
import { VoiceIntroRecorder } from "@/components/provider/VoiceIntroRecorder";
import { TOPICS, LANGUAGES } from "@/lib/constants";
import { t, type MessageKey } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";
import { completeOnboarding } from "@/app/(provider)/provider/actions";

export interface OnboardingInitial {
  displayName: string;
  bio: string;
  voiceIntroPath: string | null;
  languages: string[];
  topics: string[];
  price15: string;
  price30: string;
  price45: string;
  overage: string;
  isAvailableNow: boolean;
}

const TOTAL_STEPS = 4;

const STEPS: { numeral: string; labelKey: MessageKey }[] = [
  { numeral: "01", labelKey: "provider.stepVoiceNav" },
  { numeral: "02", labelKey: "provider.stepTopicsNav" },
  { numeral: "03", labelKey: "provider.stepPricingNav" },
  { numeral: "04", labelKey: "provider.stepVerifyNav" },
];

function dollarsToCents(value: string): number {
  const n = Number(value);
  return Number.isFinite(n) && n >= 0 ? Math.round(n * 100) : 0;
}

export function OnboardingFlow({
  providerId,
  initial,
  keepPct,
  feePct,
}: {
  providerId: string;
  initial: OnboardingInitial;
  keepPct: number;
  feePct: number;
}) {
  const router = useRouter();
  const { announce } = useToast();
  const [step, setStep] = React.useState(1);
  const [submitting, setSubmitting] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  const [displayName, setDisplayName] = React.useState(initial.displayName);
  const [bio, setBio] = React.useState(initial.bio);
  const [voiceIntroPath, setVoiceIntroPath] = React.useState(initial.voiceIntroPath);
  const [topics, setTopics] = React.useState<string[]>(initial.topics);
  const [languages, setLanguages] = React.useState<string[]>(initial.languages);
  const [price15, setPrice15] = React.useState(initial.price15);
  const [price30, setPrice30] = React.useState(initial.price30);
  const [price45, setPrice45] = React.useState(initial.price45);
  const [overage, setOverage] = React.useState(initial.overage);
  const [isAvailableNow, setIsAvailableNow] = React.useState(initial.isAvailableNow);

  const headingRef = React.useRef<HTMLHeadingElement | null>(null);
  React.useEffect(() => {
    headingRef.current?.focus();
  }, [step]);

  function toggle(list: string[], value: string): string[] {
    return list.includes(value)
      ? list.filter((v) => v !== value)
      : [...list, value];
  }

  function goNext() {
    if (step < TOTAL_STEPS) {
      setStep(step + 1);
      announce(t("provider.stepOf", { current: step + 1, total: TOTAL_STEPS }));
    }
  }
  function goBack() {
    if (step > 1) {
      setStep(step - 1);
      announce(t("provider.stepOf", { current: step - 1, total: TOTAL_STEPS }));
    }
  }

  async function onSubmit() {
    setSubmitting(true);
    setError(null);
    const res = await completeOnboarding({
      displayName,
      bio,
      voiceIntroPath: voiceIntroPath ?? undefined,
      languages,
      topics,
      priceBlock15Cents: dollarsToCents(price15),
      priceBlock30Cents: dollarsToCents(price30),
      priceBlock45Cents: dollarsToCents(price45),
      overagePerMinCents: dollarsToCents(overage),
      isAvailableNow,
    });
    // On success the action redirects; only an error returns here.
    if (res?.error) {
      setError(res.error);
      setSubmitting(false);
    } else {
      router.push("/provider/dashboard?onboarded=1");
    }
  }

  const done = {
    voice: bio.trim().length > 0,
    topics: topics.length > 0 && languages.length > 0,
