"use client";

import * as React from "react";
import { Mic, Square, Play, Pause, Upload, CircleCheck } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { createClient } from "@/lib/supabase/client";
import { VOICE_BUCKET } from "@/lib/constants";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

interface Props {
  providerId: string;
  /** Existing stored path, if any. */
  initialPath?: string | null;
  onUploaded: (path: string | null) => void;
}

/**
 * Record (MediaRecorder) or upload a voice intro and store it in the private
 * voice-intros bucket. v2: the big round record button — the same signature
 * treatment as VoicePlayer's play control (DESIGN_SPEC_V2 §5/§6) — on a sunk
 * tile, with the action label and status line as adjacent visible text.
 * Fully labelled, keyboard-operable; degrades to file upload where recording
 * isn't available. Audio is optional — the written intro is the accessible
 * equivalent.
 */
export function VoiceIntroRecorder({ providerId, initialPath, onUploaded }: Props) {
  const { announce } = useToast();
  const [recording, setRecording] = React.useState(false);
  const [audioUrl, setAudioUrl] = React.useState<string | null>(null);
  const [playing, setPlaying] = React.useState(false);
  const [uploading, setUploading] = React.useState(false);
  const [hasIntro, setHasIntro] = React.useState(!!initialPath);
  const [error, setError] = React.useState<string | null>(null);

  const recorderRef = React.useRef<MediaRecorder | null>(null);
  const chunksRef = React.useRef<Blob[]>([]);
  const audioRef = React.useRef<HTMLAudioElement | null>(null);

  const canRecord =
    typeof window !== "undefined" &&
    typeof window.MediaRecorder !== "undefined" &&
    !!navigator.mediaDevices?.getUserMedia;

  async function upload(blob: Blob) {
    setUploading(true);
    setError(null);
    try {
      const supabase = createClient();
      const path = `${providerId}/intro.webm`;
      const { error: upErr } = await supabase.storage
        .from(VOICE_BUCKET)
        .upload(path, blob, {
          upsert: true,
          contentType: blob.type || "audio/webm",
        });
      if (upErr) throw upErr;
      setHasIntro(true);
      onUploaded(path);
      announce(t("provider.recordingReady"));
    } catch {
      setError(t("provider.recordingUnsupported"));
    } finally {
      setUploading(false);
    }
  }

  async function startRecording() {
    setError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      chunksRef.current = [];
      recorder.ondataavailable = (e) => chunksRef.current.push(e.data);
      recorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: "audio/webm" });
        if (audioUrl) URL.revokeObjectURL(audioUrl);
        setAudioUrl(URL.createObjectURL(blob));
        stream.getTracks().forEach((track) => track.stop());
        void upload(blob);
      };
      recorderRef.current = recorder;
      recorder.start();
      setRecording(true);
      announce(t("provider.recordLabel"));
    } catch {
      setError(t("provider.recordingUnsupported"));
    }
  }

  function stopRecording() {
    recorderRef.current?.stop();
    setRecording(false);
  }

  function togglePlay() {
    const el = audioRef.current;
    if (!el) return;
    if (playing) {
      el.pause();
      setPlaying(false);
    } else {
      void el.play();
      setPlaying(true);
    }
  }

  async function onFile(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    if (audioUrl) URL.revokeObjectURL(audioUrl);
    setAudioUrl(URL.createObjectURL(file));
    await upload(file);
  }

  const actionLabel = recording
    ? t("provider.stopLabel")
    : hasIntro
      ? t("provider.rerecordLabel")
      : t("provider.recordLabel");

  return (
    <div className="flex flex-col gap-4 rounded-tile bg-surface-sunk p-5">
      <div className="flex items-center gap-4">
        {canRecord ? (
          <button
            type="button"
            onClick={recording ? stopRecording : startRecording}
            disabled={uploading}
            aria-pressed={recording}
            aria-label={actionLabel}
            className={[
              "grid size-[72px] flex-none place-items-center rounded-pill text-surface shadow-sm",
              "transition-[background-color,transform] duration-200 ease-[cubic-bezier(0.33,0.1,0.25,1)]",
              "active:scale-[0.96] disabled:cursor-not-allowed disabled:opacity-60",
              recording
                ? "bg-alert hover:brightness-95"
                : "bg-primary hover:bg-primary-dark",
            ].join(" ")}
          >
            {recording ? (
              <Square size={28} strokeWidth={2} aria-hidden="true" />
            ) : (
              <Mic size={28} strokeWidth={2} aria-hidden="true" />
            )}
          </button>
        ) : null}
        <div className="flex min-w-0 flex-1 flex-col gap-1">
          <span className="text-base font-bold text-ink">{actionLabel}</span>
          <span
            className="flex items-center gap-2 text-sm text-ink-soft"
            aria-live="polite"
          >
            {hasIntro ? (
              <>
                <CircleCheck
                  size={16}
                  strokeWidth={2}
                  aria-hidden="true"
                  className="flex-none text-success"
                />
                {t("provider.recordingReady")}
              </>
            ) : uploading ? (
              t("ui.loading")
            ) : (
              t("provider.recordingNone")
            )}
          </span>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-3 border-t border-border pt-4">
        {audioUrl ? (
          <Button
            variant="ghost"
            icon={playing ? Pause : Play}
            onClick={togglePlay}
          >
            {playing ? t("provider.pauseLabel") : t("provider.playLabel")}
          </Button>
        ) : null}

        <label className="inline-flex min-h-12 cursor-pointer items-center gap-2 rounded-pill border border-border-strong px-6 text-base font-extrabold text-primary transition-colors duration-200 hover:bg-primary-tint has-[:focus-visible]:shadow-[0_0_0_3px_var(--color-focus)]">
          <Upload size={20} strokeWidth={2} aria-hidden="true" />
          {t("provider.uploadLabel")}
          <input
            type="file"
            accept="audio/*"
            className="sr-only"
            onChange={onFile}
            disabled={uploading}
          />
        </label>
      </div>

      {error ? (
        <p role="alert" className="text-base font-semibold text-alert">
          {error}
        </p>
      ) : null}

      {audioUrl ? (
        <audio
          ref={audioRef}
          src={audioUrl}
          onEnded={() => setPlaying(false)}
          className="sr-only"
        />
      ) : null}
    </div>
  );
}

import { Container } from "@/components/shared/Container";
import {
  OnboardingFlow,
  type OnboardingInitial,
} from "@/components/provider/OnboardingFlow";
import { requireRole } from "@/lib/auth";
import { getOwnProvider } from "@/lib/db/queries";
import { getCommissionRate } from "@/lib/pricing";
import { t } from "@/lib/i18n";

export const metadata = {
  title: `${t("provider.onboardingTitle")} · ${t("app.name")}`,
};

function centsToDollars(cents: number): string {
  return cents > 0 ? (cents / 100).toString() : "";
}

export default async function OnboardingPage() {
  const profile = await requireRole("provider");
  const provider = await getOwnProvider();

  // Derive the take-home / fee split from the live commission rate (never a
  // hardcoded literal — CLAUDE.md rule 3).
  const feePct = Math.round(getCommissionRate() * 100);
  const keepPct = 100 - feePct;

  const initial: OnboardingInitial = {
    displayName: provider?.display_name || profile.full_name || "",
    bio: provider?.bio ?? "",
    voiceIntroPath: provider?.voice_intro_path ?? null,
    languages: provider?.languages ?? [],
    topics: provider?.topics ?? [],
    price15: centsToDollars(provider?.price_block_15_cents ?? 0),
    price30: centsToDollars(provider?.price_block_30_cents ?? 0),
    price45: centsToDollars(provider?.price_block_45_cents ?? 0),
    overage: centsToDollars(provider?.overage_per_min_cents ?? 0),
    isAvailableNow: provider?.is_available_now ?? false,
  };

  return (
    <Container className="flex flex-col gap-12 max-md:gap-8">
      <header className="flex max-w-[42ch] flex-col gap-3">
        <p className="kicker">{t("provider.onboardingKicker")}</p>
        <h1 className="font-display text-display font-bold leading-tight tracking-[-0.015em]">
          {t("provider.onboardingTitle")}
        </h1>
      </header>
      <OnboardingFlow
        providerId={profile.id}
        initial={initial}
        keepPct={keepPct}
        feePct={feePct}
      />
    </Container>
  );
}

import { notFound, redirect } from "next/navigation";
import { Container } from "@/components/shared/Container";
import { ProviderSessionFlow } from "@/components/session/ProviderSessionFlow";
import { requireRole } from "@/lib/auth";
import { getBooking } from "@/lib/db/queries";

export default async function ProviderSessionPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const profile = await requireRole("provider");
  const { id } = await params;
  const booking = await getBooking(id);
  if (!booking || booking.provider_id !== profile.id) notFound();
  if (booking.status === "completed") {
    redirect(`/provider/session/${id}/summary`);
  }

  return (
    <Container>
      <ProviderSessionFlow
        bookingId={id}
        blockMinutes={booking.block_minutes}
        alreadyInProgress={booking.status === "in_progress"}
      />
    </Container>
  );
}

"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import { Phone, PhoneOff } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Avatar } from "@/components/ui/Avatar";
import { CallStage } from "@/components/session/CallStage";
import { startSession, endSession } from "@/app/(customer)/session/actions";
import { t } from "@/lib/i18n";

const GUEST = "Guest";
const GUEST_COLOR = "#7A6A58";

export function ProviderSessionFlow({
  bookingId,
  blockMinutes,
  alreadyInProgress,
}: {
  bookingId: string;
  blockMinutes: number;
  alreadyInProgress: boolean;
}) {
  const router = useRouter();
  const [phase, setPhase] = React.useState<"incoming" | "incall">(
    alreadyInProgress ? "incall" : "incoming",
  );
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  async function accept() {
    setBusy(true);
    setError(null);
    const res = await startSession(bookingId);
    if (res.error) {
      setError(res.error);
      setBusy(false);
      return;
    }
    setPhase("incall");
  }

  if (phase === "incall") {
    return (
      <CallStage
        name={GUEST}
        avatarColor={GUEST_COLOR}
        endLabel={t("session.endForSafety")}
        onEnd={async (elapsed) => {
          await endSession(bookingId, elapsed);
          router.push(`/provider/session/${bookingId}/summary`);
        }}
      />
    );
  }

  return (
    <Card className="mx-auto flex w-full max-w-xl flex-col items-center gap-7 p-10 text-center max-md:p-6">
      <Avatar name={GUEST} color={GUEST_COLOR} size={96} />
      <div className="flex flex-col gap-2.5">
        <h1 className="text-h1">{t("session.incomingTitle", { name: GUEST })}</h1>
        <p className="text-lg text-ink-soft">
          {t("session.incomingBlock", { minutes: blockMinutes })}
        </p>
      </div>

      {error ? (
        <p role="alert" className="text-base font-semibold text-alert">
          {error}
        </p>
      ) : null}

      <div className="flex w-full flex-col gap-3 border-t border-border pt-6">
        <Button full icon={Phone} onClick={accept} disabled={busy}>
          {busy ? t("ui.loading") : t("session.accept")}
        </Button>
        <Button
          full
          variant="ghost"
          icon={PhoneOff}
          onClick={() => router.push("/provider/dashboard")}
        >
          {t("session.decline")}
        </Button>
      </div>
    </Card>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { CircleCheck } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Container } from "@/components/shared/Container";
import { requireRole } from "@/lib/auth";
import { getBooking, getSessionByBooking } from "@/lib/db/queries";
import { formatCents } from "@/lib/format";
import { t } from "@/lib/i18n";

function fmtDuration(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

export default async function ProviderSessionSummaryPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const profile = await requireRole("provider");
  const { id } = await params;
  const [booking, session] = await Promise.all([
    getBooking(id),
    getSessionByBooking(id),
  ]);
  if (!booking || booking.provider_id !== profile.id || !session) notFound();

  return (
    <Container>
      <div className="mx-auto flex w-full max-w-xl flex-col gap-8">
        <header className="flex flex-col gap-3">
          <p className="kicker flex items-center gap-2">
            <CircleCheck size={18} strokeWidth={2} aria-hidden="true" className="text-success" />
            {t("provider.summaryKicker")}
          </p>
          <h1 className="text-h1">{t("session.providerSummaryTitle")}</h1>
        </header>

        {/* Flat editorial summary — hairline rows, oversized serif amount. */}
        <dl className="flex flex-col">
          <div className="flex items-baseline justify-between gap-4 border-t border-border py-4 text-base">
            <dt className="text-ink-soft">{t("session.providerDuration")}</dt>
            <dd className="font-display text-h3 tabular-nums text-ink">
              {fmtDuration(session.elapsed_seconds)}
            </dd>
          </div>
          <div className="flex flex-wrap items-baseline justify-between gap-4 border-y border-border py-6">
            <dt className="text-base font-bold text-ink">
              {t("session.providerEarned")}
            </dt>
            <dd className="numeral text-primary">
              {formatCents(session.provider_earnings_cents)}
            </dd>
          </div>
        </dl>

        <Link href="/provider/dashboard" className="self-start rounded-pill">
          <Button>{t("session.backToDashboard")}</Button>
        </Link>
      </div>
    </Container>
  );
}

