it("exposes a switch with aria-checked and a text label (not colour alone)", async () => {
  const { container } = renderWithProviders(
    <AvailabilityToggle initial={false} />,
  );
  const sw = screen.getByRole("switch");
  expect(sw).toHaveAttribute("aria-checked", "false");
  // State is conveyed by visible text: the band's serif status line plus
  // the switch's own action label — never colour alone.
  expect(sw).toHaveTextContent(/go available/i);
  expect(screen.getByText(/you're offline/i)).toBeInTheDocument();
  expect(await axe(container)).toHaveNoViolations();
});

